<script setup lang="ts">
import {cloneDraft,pendingMutation} from "../../../shared/drafts";
import{ref,computed,onMounted,onUnmounted,watch}from'vue';import{api,ApiError}from'../app/api';import Icon from'../ui/Icon.vue';import Modal from'../ui/Modal.vue';import RouteMap from'./RouteMap.vue';import EntityEditor from'./EntityEditor.vue';import{categories,modes,type Snapshot,type Entity,type Kind,type Data}from'../../../shared/model';import{travelForDay,planTimes,scheduleLegs,balances,suggestClothes,mergePackingTemplate,type LegResult}from'../../../shared/domain';
const pendingCommands=new Map<string,any>();
const tripFormVersion=ref(0),settingsError=ref(''),pendingPoint=ref<{entity:Entity;lat:number;lng:number}|null>(null),pointError=ref('');let sheetDragged=false,suppressSheetClickUntil=0;
const viewportHeight=()=>window.innerHeight;
const props=defineProps<{tripId:string;user:any}>();const emit=defineEmits<{back:[];logout:[]}>();const snap=ref<Snapshot|null>(null),tab=ref('plan'),day=ref<string|null>(null),selected=ref<string|null>(null),error=ref(''),toast=ref(''),sync=ref('连接中'),busy=ref(false),search=ref(''),memberFilter=ref('all'),unpacked=ref(false),categoryFilter=ref('all');const editor=ref<{kind:Kind;entity:Entity|null;draftId:string}|null>(null),editorError=ref(''),conflict=ref<any>(undefined),dialog=ref(''),link=ref(''),inviteRole=ref('editor'),invites=ref<any[]>([]),picking=ref(false),routes=ref<{from:string;to:string;result:LegResult}[]>([]),routeBusy=ref(false),weatherValue=ref<any>(null),templateDays=ref(7),templatePerson=ref(''),templatePreview=ref<Data[]>([]),tripForm=ref<Data>({});let events:EventSource|undefined,routeGeneration=0,weatherGeneration=0,refreshId=0;const sheetHeight=ref<number|null>(null);let dragStart=0,dragHeight=0,dragAt=0;let toastTimer:ReturnType<typeof setTimeout>;
const navigation=[['plan','map','规划'],['bookings','hotel','预订'],['guides','book','攻略'],['ledger','wallet','账本'],['packing','bag','准备']];const all=computed(()=>snap.value?.entities||[]);const entities=(kind:Kind)=>all.value.filter(e=>e.kind===kind);const participants=computed(()=>entities('participant'));const writable=computed(()=>snap.value&&snap.value.role!=='viewer'&&!snap.value.archived);const dayItems=computed(()=>{const d=snap.value?.days.find(d=>d.date===day.value);return(d?.itemIds||[]).map(id=>all.value.find(e=>e.id===id)).filter(Boolean)as Entity[]});const summaries=computed(()=>day.value&&snap.value?travelForDay(day.value,snap.value.timeZone,entities('transport').map(e=>e.data),entities('stay').map(e=>e.data)):[]);const times=computed(()=>planTimes(dayItems.value.map(e=>({...e.data,id:e.id})),scheduleLegs(dayItems.value.map(e=>({...e.data,id:e.id})),routes.value)));
const packing=computed(()=>entities('packing').filter(e=>(categoryFilter.value==='all'||e.data.category===categoryFilter.value)&&(memberFilter.value==='all'||(e.data.participantId||'public')===memberFilter.value)&&(!unpacked.value||!e.data.packed)&&`${e.data.name} ${e.data.note}`.toLowerCase().includes(search.value.toLowerCase())));const packed=computed(()=>entities('packing').filter(e=>e.data.packed).length);const guides=computed(()=>entities('guide').filter(e=>`${e.data.title} ${e.data.content} ${e.data.sourceText}`.toLowerCase().includes(search.value.toLowerCase())));const totals=computed(()=>balances(entities('expense').map(e=>e.data),entities('settlement').map(e=>e.data)));const totalSpent=computed(()=>entities('expense').reduce((s,e)=>s+e.data.amount,0));const name=(id:string|null)=>participants.value.find(e=>e.id===id)?.data.name||'公共物品';const money=(n:number)=>(n/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
function notify(t:string){toast.value=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3500)}
async function refresh(){const request=++refreshId;try{const value=await api<Snapshot>(`/trips/${props.tripId}/snapshot`);if(request!==refreshId)return;if(!snap.value||value.seq>=snap.value.seq)snap.value=value;if(day.value!==null&&!value.days.some(d=>d.date===day.value))day.value=value.startDate}catch(e){error.value=(e as Error).message;if([401,403].includes((e as ApiError).status)){events?.close();snap.value=null;sessionStorage.removeItem('xj-trip:'+props.user.id);if((e as ApiError).status===401)emit('logout')}}}
function connect(){events?.close();events=new EventSource(`/api/trips/${props.tripId}/events?after=${snap.value?.seq||0}`);events.onopen=()=>sync.value='已同步';events.onmessage=()=>{sync.value='已同步';void refresh()};events.onerror=()=>sync.value='连接中断，正在重连';events.addEventListener('reset',()=>void refresh());events.addEventListener('revoked',()=>{events?.close();void refresh()})}
onMounted(async()=>{await refresh();if(snap.value){day.value=snap.value.startDate;templatePerson.value=participants.value[0]?.id||'';connect()}});onUnmounted(()=>{events?.close();clearTimeout(toastTimer)});watch(()=>[day.value,dayItems.value.map(e=>`${e.id}:${JSON.stringify(e.data.place)}:${e.data.travelMode}`).join('|')],()=>{routeGeneration++;routes.value=[];weatherGeneration++;weatherValue.value=null});watch(tab,()=>search.value='');
async function command(c:Data){sync.value='正在保存';try{const value=await api<Snapshot>(`/trips/${props.tripId}/commands`,'POST',pendingMutation(c,pendingCommands));if(!snap.value||value.seq>=snap.value.seq)snap.value=value;sync.value='已同步';return true}catch(e){sync.value=navigator.onLine?'未保存':'离线 · 未同步';throw e}}
function edit(kind:Kind,entity:Entity|null=null){editor.value={kind,entity:entity?cloneDraft(entity):null,draftId:entity?.id||crypto.randomUUID()};editorError.value='';conflict.value=undefined}
async function save(data:Data,baseVersion?:number,draftId?:string){if(!editor.value)return;busy.value=true;editorError.value='';const e=editor.value;try{await command({type:'writeEntity',kind:e.kind,id:draftId||e.draftId,expectedVersion:baseVersion??e.entity?.version??0,data});sessionStorage.removeItem('xj-draft:'+props.user.id+':'+props.tripId+':'+e.kind+':'+(e.entity?.id||'new'));editor.value=null;notify('已保存，同行人会同步看到')}catch(err){editorError.value=(err as Error).message;if((err as ApiError).status===409)conflict.value=(err as ApiError).current;await refresh()}finally{busy.value=false}}
async function patch(e:Entity,data:Data){try{await command({type:'writeEntity',kind:e.kind,id:e.id,expectedVersion:e.version,data:{...e.data,...data}})}catch(err){error.value=(err as Error).message;await refresh()}}
const deletion=ref<Entity|null>(null);async function remove(){if(!deletion.value)return;try{await command({type:'deleteEntity',kind:deletion.value.kind,id:deletion.value.id,expectedVersion:deletion.value.version});deletion.value=null;selected.value=null;notify('已删除')}catch(e){error.value=(e as Error).message}}
async function move(e:Entity,date:string|null,beforeId:string|null=null){const from=snap.value!.days.find(d=>d.date===e.data.date)!,to=snap.value!.days.find(d=>d.date===date)!;try{await command({type:'moveItem',id:e.id,date,beforeId,expectedVersion:e.version,fromDayVersion:from.version,toDayVersion:to.version});day.value=date}catch(err){error.value=(err as Error).message;await refresh()}}
function reorder(e:Entity,direction:number){const list=dayItems.value,index=list.findIndex(i=>i.id===e.id);const next=direction<0?list[index-1]?.id:list[index+2]?.id||null;if(index+direction>=0&&index+direction<list.length)void move(e,day.value,next)}
function dropped(event:DragEvent,beforeId:string|null){const id=event.dataTransfer?.getData('text/plain');const e=all.value.find(e=>e.id===id&&e.kind==='item');if(e&&id!==beforeId)void move(e,day.value,beforeId)}
async function pick(lat:number,lng:number){picking.value=false;const entity=all.value.find(e=>e.id===selected.value);if(entity){pendingPoint.value={entity:cloneDraft(entity),lat,lng};pointError.value=''}else notify('请先选中一条事项')}
async function confirmPoint(){const p=pendingPoint.value;if(!p)return;try{await command({type:'writeEntity',kind:'item',id:p.entity.id,expectedVersion:p.entity.version,data:{...p.entity.data,place:{latitude:p.lat,longitude:p.lng,crs:'WGS84'},locationStatus:'unconfirmed'}});pendingPoint.value=null;notify('位置已保存，入口仍请核对')}catch(e){pointError.value=(e as Error).message}}
function adoptLatest(){const e=editor.value;if(e)sessionStorage.removeItem('xj-draft:'+props.user.id+':'+props.tripId+':'+e.kind+':'+(e.entity?.id||'new'));editor.value=null;conflict.value=undefined}
async function queryRoutes(){routeBusy.value=true;const generation=++routeGeneration;const list=[...dayItems.value];const output:typeof routes.value=[];for(let i=0;i<list.length-1;i++){const a=list[i],b=list[i+1];const booking=entities('transport').find(e=>e.data.fromItemId===a.id&&e.data.toItemId===b.id);let result:LegResult;try{result=booking?{status:'unsupported',message:`按「${booking.data.name}」安排交通`}:await api(`/trips/${props.tripId}/route`,'POST',{from:a.id,to:b.id,mode:a.data.travelMode||'driving'})}catch(e){result={status:'failed',message:(e as Error).message}}if(generation!==routeGeneration){routeBusy.value=false;return}output.push({from:a.id,to:b.id,result});routes.value=[...output]}routeBusy.value=false}
function legText(index:number){const a=dayItems.value[index],b=dayItems.value[index+1],r=routes.value.find(r=>r.from===a?.id&&r.to===b?.id)?.result;if(a?.data.manualTravelMinutes!==undefined&&a?.data.manualTravelMinutes!=='')return`手工预计 ${a.data.manualTravelMinutes} 分钟${r?.status==='ready'?' · 道路 '+(r.distanceMeters!/1000).toFixed(1)+' km':''}`;if(r?.status==='ready')return`${(r.distanceMeters!/1000).toFixed(1)} km · 预计 ${Math.ceil(r.durationSeconds!/60)} 分钟`;return r?.message||'道路耗时待查询'}
async function getWeather(){const n=++weatherGeneration;const item=dayItems.value.find(e=>e.data.place);if(!item||!day.value)return notify('请先为当天事项补充位置');try{const v=await api(`/trips/${props.tripId}/weather?item=${item.id}&date=${day.value}`);if(n===weatherGeneration)weatherValue.value=v}catch(e){if(n===weatherGeneration)notify((e as Error).message)}}
function sheetClick(){if(performance.now()<suppressSheetClickUntil)return;sheetHeight.value=sheetHeight.value===170?innerHeight*.49:170}
function sheetDown(e:PointerEvent){sheetDragged=false;(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);dragStart=e.clientY;dragHeight=sheetHeight.value||innerHeight*.49;dragAt=performance.now()}
function sheetMove(e:PointerEvent){if(!(e.currentTarget as HTMLElement).hasPointerCapture(e.pointerId))return;if(Math.abs(dragStart-e.clientY)>5)sheetDragged=true;const h=dragHeight+dragStart-e.clientY;sheetHeight.value=h<170?170+(h-170)*.2:h>innerHeight*.8?innerHeight*.8+(h-innerHeight*.8)*.2:h}
function sheetUp(e:PointerEvent){const target=e.currentTarget as HTMLElement;if(!target.hasPointerCapture(e.pointerId))return;target.releasePointerCapture(e.pointerId);if(!sheetDragged)return;suppressSheetClickUntil=performance.now()+500;const stops=[170,innerHeight*.49,innerHeight*.8];const velocity=(dragStart-e.clientY)/Math.max(1,performance.now()-dragAt);const h=(sheetHeight.value||stops[1])+velocity*100;sheetHeight.value=stops.reduce((best,x)=>Math.abs(x-h)<Math.abs(best-h)?x:best)}
async function members(){dialog.value='members';link.value='';if(snap.value?.role==='owner')invites.value=await api(`/trips/${props.tripId}/invites`)}async function invite(){try{const r=await api(`/trips/${props.tripId}/invites`,'POST',{role:inviteRole.value});link.value=location.origin+'/#invite='+encodeURIComponent(r.token);invites.value=await api(`/trips/${props.tripId}/invites`)}catch(e){error.value=(e as Error).message}}
async function revoke(id:string){await api(`/trips/${props.tripId}/invites/${id}`,'DELETE');invites.value=await api(`/trips/${props.tripId}/invites`)}async function memberAction(id:string,role?:string){try{await api(`/trips/${props.tripId}/members/${id}`,role?'PATCH':'DELETE',role?{role}:undefined);await refresh()}catch(e){error.value=(e as Error).message}}
function prepareTemplate(){templatePreview.value=suggestClothes(snap.value!.days.length-1,templateDays.value,templatePerson.value)}async function addTemplate(){busy.value=true;try{const existing=entities('packing').map(e=>e.data);const add=mergePackingTemplate(existing,templatePreview.value).slice(existing.length);for(const data of add)await command({type:'writeEntity',kind:'packing',id:crypto.randomUUID(),expectedVersion:0,data});dialog.value='';notify(`已添加 ${add.length} 项，既有物品保留`)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function exportTrip(){try{const data=await api(`/trips/${props.tripId}/export`);const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`行间-${snap.value!.title}.json`;a.click();URL.revokeObjectURL(url)}catch(e){error.value=(e as Error).message}}
function settings(){tripFormVersion.value=snap.value!.version;settingsError.value='';tripForm.value={title:snap.value!.title,startDate:snap.value!.startDate,endDate:snap.value!.endDate,timeZone:snap.value!.timeZone,archived:snap.value!.archived};dialog.value='settings'}async function saveTrip(){try{await command({type:'updateTrip',expectedVersion:tripFormVersion.value,data:tripForm.value});dialog.value=''}catch(e){settingsError.value=(e as Error).message}}
</script>
<template><div v-if="!snap" class="loading-screen"><p>{{error||'正在打开旅行…'}}</p><button class="secondary" @click="emit('back')">返回我的旅行</button></div><div v-else class="workspace"><aside class="rail"><button class="brand-mark" aria-label="我的旅行" @click="emit('back')"><Icon name="map" :size="24"/></button><span class="rail-line"></span><button class="rail-active" aria-label="当前旅行"><Icon name="calendar"/></button><div class="rail-bottom"><button class="icon-button" aria-label="设置" @click="settings"><Icon name="settings"/></button><button class="avatar" @click="emit('logout')" title="退出登录">{{user.username[0].toUpperCase()}}</button></div></aside><div class="workspace-main"><header class="trip-header"><div><button class="breadcrumb" @click="emit('back')">我的旅行 <span>/</span> 旅行工作区</button><h1>{{snap.title}} <span v-if="snap.archived" class="tag">已归档</span></h1><p><Icon name="calendar" :size="14"/>{{snap.startDate}} — {{snap.endDate}}<span>·</span>{{snap.days.length-1}} 天</p></div><div class="header-actions"><span :class="['sync-state',{warning:sync!=='已同步'}]"><i></i>{{sync}}</span><button class="secondary companions" aria-label="同行人" @click="members"><span class="avatar-stack"><i v-for="m in snap.members.slice(0,3)">{{m.username[0].toUpperCase()}}</i></span>同行人</button><button class="icon-button mobile-settings" aria-label="设置" @click="settings"><Icon name="settings"/></button></div></header><nav class="module-nav"><button v-for="n in navigation" :key="n[0]" :class="{active:tab===n[0]}" @click="tab=n[0]"><Icon :name="n[1]" :size="19"/>{{n[2]}}</button><span class="nav-note">共同规划，慢慢出发。</span></nav>
<div v-if="error" class="inline-error" role="alert">{{error}}<button @click="error=''">关闭</button></div>
<main v-if="tab==='plan'" class="planner"><div class="planner-map"><RouteMap :items="dayItems" :selected="selected" :routes="routes" :picking="picking" @select="selected=$event" @pick="pick"/><div class="map-caption"><span class="eyebrow">MAKE ROOM FOR THE UNEXPECTED</span><h3>路线在心里，风景在路上。</h3></div></div><section class="day-panel" :style="sheetHeight?{'--sheet-height':sheetHeight+'px'}:{}"><button class="sheet-handle" aria-label="拖动或切换日程面板高度" @pointerdown="sheetDown" @pointermove="sheetMove" @pointerup="sheetUp" @click="sheetClick"><span></span></button><div class="day-rail"><button :class="{active:day===null}" @click="day=null">待规划<span>{{snap.days.find(d=>d.date===null)?.itemIds.length||0}}</span></button><button v-for="(d,i) in snap.days.filter(d=>d.date)" :class="{active:day===d.date}" @click="day=d.date"><small>DAY {{i+1}}</small>{{d.date!.slice(5).replace('-','.')}}</button></div><div class="day-heading"><div><span class="eyebrow">{{day?'DAILY ITINERARY':'YOUR WISH LIST'}}</span><h2>{{day?'这一天，慢慢逛':'先收藏，再出发'}}<span>{{dayItems.length}} 站</span></h2></div><button class="icon-button" title="按需查看天气" aria-label="查看天气" @click="getWeather"><Icon name="sun"/></button></div><p v-if="weatherValue" class="weather-line">{{weatherValue.status==='ready'?`${weatherValue.low??'—'}° — ${weatherValue.high??'—'}° · 降水 ${weatherValue.rain??'—'}% · Open-Meteo`:weatherValue.status==='outside-window'?'该日期暂无天气预报':'天气暂不可用，可稍后重试'}}</p><div class="day-scroll" @dragover.prevent @drop.prevent="dropped($event,null)"><div v-if="summaries.length" class="travel-summary"><div v-for="s in summaries"><span>{{s.type}}</span><strong>{{s.name}}</strong><small>{{s.time}}</small></div></div><div v-if="!dayItems.length" class="empty-state"><Icon name="pin" :size="36"/><h3>{{day?'今天想去哪里？':'留住旅行的灵感'}}</h3><p>添加想去的地点，<br>和同行人一起安排顺序。</p></div><template v-for="(item,i) in dayItems" :key="item.id"><article :class="['itinerary-card',{selected:selected===item.id,completed:item.data.completed}]" @click="selected=item.id" @dragover.prevent.stop @drop.prevent.stop="dropped($event,item.id)"><div class="itinerary-top"><button class="stop-number" :draggable="!!writable" @dragstart="($event.dataTransfer!).setData('text/plain',item.id)" :aria-label="'选择 '+item.data.name">{{i+1}}</button><div class="stop-info"><span class="stop-time">{{item.data.fixedTime||'时间自由'}}<small> · {{item.data.durationMinutes}} 分钟</small></span><h3>{{item.data.name}}</h3><p>{{item.data.note|| (item.data.place?'位置已保存，入口请核对':'尚未补充位置')}}</p></div><input type="checkbox" :checked="item.data.completed" :disabled="!writable" :aria-label="'完成 '+item.data.name" @click.stop @change="patch(item,{completed:!item.data.completed})"></div><div class="stop-meta"><span :class="['tag',item.data.place?'blue':'']"><Icon name="pin" :size="12"/>{{item.data.place?'已定位':item.data.locationStatus==='not-needed'?'无需定位':'待定位'}}</span><button v-if="writable" class="text-button" @click.stop="edit('item',item)">编辑</button></div><div v-if="selected===item.id&&writable" class="item-actions"><button @click.stop="reorder(item,-1)" :disabled="i===0">上移</button><button @click.stop="reorder(item,1)" :disabled="i===dayItems.length-1">下移</button><select aria-label="移动到日期" :value="item.data.date||''" @click.stop @change="move(item,($event.target as HTMLSelectElement).value||null)"><option value="">待规划</option><option v-for="d in snap.days.filter(d=>d.date)" :value="d.date!">{{d.date}}</option></select><button @click.stop="picking=true;sheetHeight=170">地图选点</button><button class="danger" @click.stop="deletion=item">删除</button></div><p v-if="times[i]?.conflictMinutes" class="error small">按当前路段预计晚到 {{times[i].conflictMinutes}} 分钟</p></article><div v-if="i<dayItems.length-1" class="leg-row"><Icon :name="item.data.travelMode==='walking'?'pin':'car'" :size="14"/><span>{{modes.find(m=>m[0]===item.data.travelMode)?.[1]||'自驾'}} · {{legText(i)}}</span></div></template><button v-if="writable" class="add-stop" @click="edit('item')"><Icon name="plus" :size="18"/>添加地点</button></div><footer class="day-footer"><span><Icon name="map" :size="16"/>{{dayItems.filter(e=>e.data.place).length}} / {{dayItems.length}} 已定位</span><button class="text-button" :disabled="routeBusy||dayItems.length<2" @click="queryRoutes">{{routeBusy?'正在查询…':'查询道路路线'}} <Icon name="arrow" :size="15"/></button></footer></section></main>
<main v-else class="content-page"><template v-if="tab==='packing'"><div class="section-heading"><div><span class="eyebrow">LESS TO WORRY ABOUT</span><h2>轻装，也安心。</h2><p>每个人准备一点，一起带上期待。</p></div><button v-if="writable" class="primary" @click="edit('packing')"><Icon name="plus" :size="18"/>添加物品</button></div><div class="packing-overview"><div class="packing-progress"><span class="packing-illustration"><Icon name="bag" :size="42"/></span><div><h3>出发准备 <span>{{packed}} / {{entities('packing').length}}</span></h3><div class="progress-track"><i :style="{width:(packed/Math.max(1,entities('packing').length)*100)+'%'}"></i></div><small>{{entities('packing').length-packed}} 项待准备 · 一起分工，不用重复带</small></div><button v-if="writable" class="secondary" @click="dialog='template';templatePreview=[]">衣物建议</button></div><div class="category-grid"><button v-for="(c,i) in categories" :class="{active:categoryFilter===c[0]}" @click="categoryFilter=categoryFilter===c[0]?'all':c[0]"><span :class="'category-symbol cat-'+i"><Icon :name="['bag','book','sun','cloud','check','car'][i]" :size="22"/></span><strong>{{c[1]}}</strong><small>{{entities('packing').filter(e=>e.data.category===c[0]&&e.data.packed).length}} / {{entities('packing').filter(e=>e.data.category===c[0]).length}}</small></button></div></div><div class="list-toolbar"><label class="search-box"><Icon name="search" :size="17"/><input v-model="search" placeholder="找一件物品" aria-label="搜索物品"></label><select v-model="memberFilter" aria-label="按成员筛选"><option value="all">所有同行人</option><option value="public">公共物品</option><option v-for="p in participants" :value="p.id">{{p.data.name}}</option></select><label class="check-label"><input v-model="unpacked" type="checkbox">只看未准备</label><button v-if="writable" class="text-button" @click="edit('participant')">添加参与者</button></div><div class="packing-list"><div v-for="item in packing" :key="item.id" :class="['packing-row',{done:item.data.packed}]"><input type="checkbox" :checked="item.data.packed" :disabled="!writable" :aria-label="'准备好 '+item.data.name" @change="patch(item,{packed:!item.data.packed})"><button class="packing-title" @click="writable&&edit('packing',item)"><strong>{{item.data.name}}</strong><small>{{item.data.note||categories.find(c=>c[0]===item.data.category)?.[1]}}</small></button><span class="tag">{{item.data.carryMode==='wear'?'出发时穿':'装包'}} · {{item.data.quantity}}</span><span class="assignee"><i>{{name(item.data.participantId)[0]}}</i>{{name(item.data.participantId)}}</span><button v-if="writable" class="icon-button" :aria-label="'删除 '+item.data.name" @click="deletion=item"><Icon name="close" :size="15"/></button></div><div v-if="!packing.length" class="empty-state"><Icon name="bag" :size="36"/><h3>还没有符合条件的物品</h3><p>添加物品，或调整筛选条件。</p></div></div></template>
<template v-else-if="tab==='bookings'"><div class="section-heading"><div><span class="eyebrow">EVERY CONNECTION COUNTS</span><h2>路上有安排，心里有着落。</h2><p>交通、住宿和跨夜衔接，在这里一起核对。</p></div><div class="button-row" v-if="writable"><button class="secondary" @click="edit('stay')">添加住宿</button><button class="primary" @click="edit('transport')"><Icon name="plus" :size="18"/>添加交通</button></div></div><h3 class="section-label">交通安排 <span>{{entities('transport').length}}</span></h3><div class="booking-grid"><article class="booking-card" v-for="t in entities('transport')"><header><span class="category-symbol cat-5"><Icon name="car"/></span><div><h3>{{t.data.name}}</h3><small>{{modes.find(m=>m[0]===t.data.mode)?.[1]}} · {{t.data.status==='booked'?'已预订':'计划中'}}</small></div><button v-if="writable" class="text-button" @click="edit('transport',t)">编辑</button></header><div class="transport-route"><div><strong>{{t.data.departure?.local?.slice(11)||'待定'}}</strong><span>{{t.data.fromName}}</span><small>{{t.data.departure?.local?.slice(0,10)||'日期未填写'}}</small></div><span class="transport-line"><Icon name="arrow"/></span><div><strong>{{t.data.arrival?.local?.slice(11)||'待定'}}</strong><span>{{t.data.toName}}</span><small>{{t.data.arrival?.local?.slice(0,10)||'日期未填写'}}</small></div></div><p class="small muted">{{t.data.note||'请以实际票面、班次和出发地点为准。'}}</p><button v-if="writable" class="text-button danger" @click="deletion=t">删除记录</button></article><div v-if="!entities('transport').length" class="empty-card">添加第一段交通，跨夜到达也能清楚安排。</div></div><h3 class="section-label">住宿安排 <span>{{entities('stay').length}}</span></h3><div class="booking-grid"><article v-for="s in entities('stay')" class="booking-card"><header><span class="category-symbol cat-0"><Icon name="hotel"/></span><div><h3>{{s.data.name}}</h3><small>{{s.data.status==='booked'?'已预订':'计划中'}}</small></div><button v-if="writable" class="text-button" @click="edit('stay',s)">编辑</button></header><div class="stay-dates"><span>入住<strong>{{s.data.checkIn}}</strong><small>{{s.data.checkInTime||'待核对'}}</small></span><span>退房<strong>{{s.data.checkOut}}</strong><small>{{s.data.checkOutTime||'待核对'}}</small></span></div><p class="muted small">{{s.data.address||'地址待补充'}}</p><button v-if="writable" class="text-button danger" @click="deletion=s">删除记录</button></article><div v-if="!entities('stay').length" class="empty-card">多晚住宿只记一次，每晚行程会自动显示。</div></div></template>
<template v-else-if="tab==='guides'"><div class="section-heading"><div><span class="eyebrow">GOOD IDEAS, ALL TOGETHER</span><h2>把灵感，留在这里。</h2><p>收藏攻略、交通提醒和出行备忘。</p></div><button v-if="writable" class="primary" @click="edit('guide')">添加攻略</button></div><label class="search-box"><Icon name="search"/><input v-model="search" placeholder="搜索攻略" aria-label="搜索攻略"></label><div class="guide-grid"><article v-for="g in guides" class="guide-card"><span class="tag blue">{{g.data.category==='guide'?'游玩攻略':g.data.category==='transport'?'交通提醒':'出行备忘'}}</span><h3>{{g.data.title}}</h3><p>{{g.data.content}}</p><small class="muted">{{g.data.dates?.join(' · ')}}</small><footer><a v-if="g.data.sourceUrl" :href="g.data.sourceUrl" target="_blank" rel="noopener noreferrer">查看来源 ↗</a><button v-if="writable" class="text-button" @click="edit('guide',g)">编辑</button><button v-if="writable" class="text-button danger" @click="deletion=g">删除</button></footer></article><div v-if="!guides.length" class="empty-card">把值得记住的旅行信息放进来，同行人也能看到。</div></div></template>
<template v-else-if="tab==='ledger'"><div class="section-heading"><div><span class="eyebrow">SHARE THE JOURNEY, SHARE THE COST</span><h2>账目清楚，相处轻松。</h2><p>订单与实际支出分开记录，人民币计价。</p></div><div class="button-row" v-if="writable"><button class="secondary" @click="edit('settlement')">记录结清</button><button class="primary" @click="edit('expense')">记一笔</button></div></div><div class="ledger-summary"><div><small>旅行总支出</small><h2><span>¥</span>{{money(totalSpent)}}</h2></div><div v-for="p in participants"><small>{{p.data.name}}</small><strong>{{(totals[p.id]||0)>=0?'待收':'待付'}} ¥{{money(Math.abs(totals[p.id]||0))}}</strong></div></div><div class="packing-list"><div v-for="e in entities('expense')" class="expense-row"><span class="category-symbol cat-4"><Icon name="wallet"/></span><div><h3>{{e.data.title}}</h3><small>{{e.data.date}} · {{name(e.data.payer)}}付款 · {{e.data.category}}</small></div><strong>¥{{money(e.data.amount)}}</strong><button v-if="writable" class="text-button" @click="edit('expense',e)">编辑</button><button v-if="writable" class="text-button danger" @click="deletion=e">删除</button></div><div v-if="!entities('expense').length" class="empty-card">还没有支出，住宿订单不会自动重复记账。</div></div><h3 class="section-label">结清记录</h3><div class="expense-row" v-for="s in entities('settlement')"><div>{{name(s.data.from)}} → {{name(s.data.to)}}<small>{{s.data.date}}</small></div><strong>¥{{money(s.data.amount)}}</strong><button v-if="writable" class="text-button" @click="edit('settlement',s)">编辑</button><button v-if="writable" class="text-button danger" @click="deletion=s">删除</button></div></template></main>
</div><div v-if="toast" class="toast" role="status"><Icon name="check" :size="17"/>{{toast}}</div>
<EntityEditor v-if="editor" :user-id="user.id" :draft-id="editor.draftId" :kind="editor.kind" :entity="editor.entity" :snapshot="snap" :date="day" :error="editorError" :busy="busy" :remote-changed="!!editor.entity&&all.find(e=>e.id===editor!.entity!.id)?.version!==editor.entity.version" @save="save" @close="editor=null"/>
<Modal v-if="conflict!==undefined" title="同行人更新了这项内容" @close="conflict=undefined"><p>你的草稿仍保留。先核对最新版本，再决定如何保存。</p><pre class="conflict-preview">{{JSON.stringify(conflict?.data,null,2)||'这项内容已经被删除'}}</pre><div class="button-row"><button class="secondary" @click="adoptLatest">采用最新内容</button><button v-if="conflict&&editor" class="primary" @click="editor.entity={...editor.entity!,version:conflict.version};conflict=undefined;editorError=''">保留草稿，重新提交</button></div></Modal>
<Modal v-if="pendingPoint" title="确认这个位置？" @close="pendingPoint=null"><p>将为「{{pendingPoint.entity.data.name}}」保存所选位置。此操作不会确认景区入口。</p><p class="muted">{{pendingPoint.lat.toFixed(6)}}，{{pendingPoint.lng.toFixed(6)}}</p><p v-if="pointError" class="error">{{pointError}}</p><div class="button-row"><button class="secondary" @click="pendingPoint=null">取消</button><button class="primary" @click="confirmPoint">确认位置</button></div></Modal><Modal v-if="deletion" title="删除这条记录？" @close="deletion=null"><p>将从共同旅行中删除「{{deletion.data.name||deletion.data.title||'结清记录'}}」。{{deletion.kind==='item'?'相关攻略与交通保留，事项关联将解除。':''}}</p><div class="button-row"><button class="secondary" @click="deletion=null">取消</button><button class="primary destructive" @click="remove">确认删除</button></div></Modal>
<Modal v-if="dialog==='members'" title="一起规划的人" @close="dialog=''"><p class="muted">这趟旅行仅以下同行人可见。</p><div class="member-row" v-for="m in snap.members"><i class="avatar">{{m.username[0].toUpperCase()}}</i><strong>{{m.username}}</strong><span v-if="m.role==='owner'" class="tag">拥有者</span><select v-else-if="snap.role==='owner'" :value="m.role" :aria-label="m.username+'权限'" @change="memberAction(m.id,($event.target as HTMLSelectElement).value)"><option value="editor">可编辑</option><option value="viewer">仅查看</option></select><span v-else class="tag">{{m.role==='editor'?'可编辑':'仅查看'}}</span><button v-if="snap.role==='owner'&&m.role!=='owner'" class="text-button danger" @click="memberAction(m.id)">移除</button></div><template v-if="snap.role==='owner'"><hr><label>邀请权限<select v-model="inviteRole"><option value="editor">共同编辑</option><option value="viewer">仅查看</option></select></label><button class="primary full" @click="invite">生成邀请链接</button><label v-if="link">邀请链接<input :value="link" readonly @focus="($event.target as HTMLInputElement).select()"></label><p class="muted small">链接 7 天内有效，仅可接受一次。请自行发给同行人。</p><div v-for="i in invites.filter(i=>!i.used&&!i.revoked)" class="invite-row"><small>有效至 {{new Date(i.expires).toLocaleDateString()}}</small><button class="text-button danger" @click="revoke(i.id)">撤销邀请</button></div></template></Modal>
<Modal v-if="dialog==='template'" title="按行程准备衣物" @close="dialog=''"><p class="muted">按天数和洗换习惯估算，可在添加后逐项调整。</p><label>为谁准备<select v-model="templatePerson"><option v-for="p in participants" :value="p.id">{{p.data.name}}</option></select></label><label>每隔几天洗换<input v-model.number="templateDays" type="number" min="1" max="366"></label><button class="secondary full" @click="prepareTemplate">预览建议</button><div v-for="p in templatePreview" class="template-row"><span>{{p.name}} × {{p.quantity}}</span><span class="tag">{{p.carryMode==='wear'?'出发时穿':'装包'}}</span></div><button v-if="templatePreview.length" class="primary full" :disabled="busy" @click="addTemplate">添加缺少的物品</button></Modal>
<Modal v-if="dialog==='settings'" title="旅行设置" @close="dialog=''"><form class="editor-form" @submit.prevent="saveTrip"><label>旅行名称<input v-model="tripForm.title" :disabled="snap.role!=='owner'" required></label><div class="form-grid"><label>开始日期<input v-model="tripForm.startDate" type="date" :disabled="snap.role!=='owner'" required></label><label>结束日期<input v-model="tripForm.endDate" type="date" :disabled="snap.role!=='owner'" required></label></div><label>时区<input v-model="tripForm.timeZone" :disabled="snap.role!=='owner'"></label><label class="check-label"><input v-model="tripForm.archived" type="checkbox" :disabled="snap.role!=='owner'">归档这趟旅行</label><p v-if="settingsError" class="error" role="alert">{{settingsError}}</p><button v-if="settingsError" type="button" class="secondary" @click="settings">加载最新设置</button><button v-if="snap.role==='owner'" class="primary full">保存设置</button></form><hr><button class="secondary full" :disabled="snap.role==='viewer'" @click="exportTrip"><Icon name="download"/>导出本趟旅行 JSON</button><p class="muted small">导出包含私人旅行资料，请妥善保管。不会自动同步到旧小程序。</p><button class="text-button" @click="emit('logout')">退出当前账号</button></Modal>
</div></template>




